print(r.area)

class Matematica:
    @staticmethod
    def dobro(n):
        return n * 2

print(Matematica.dobro(5))
print(Matematica().dobro(1))

class Data:
    def __init__(self, d, m):
        self.d, self.m = d, m

    @classmethod
    def de_texto(cls, texto):
        d, m = map(int, texto.split("/"))
        return cls(d, m)

x = Data.de_texto("07/10")
print(x.d, x.m)

